 "model": {
  "variables": [
   {
    "name": "strawberry acres",
    "lower": 0.0,
    "upper": null,
    "integer": false
   },
   {
    "name": "watermelon acres",
    "lower": 0.0,
    "upper": null,
    "integer": false
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "strawberry acres",
     "coef": 200.0
    },
    {
     "var": "watermelon acres",
     "coef": 500.0
    }
   ]
  },
  "constraints": [
   {
    "name": "land",
    "terms": [
     {
      "var": "strawberry acres",
      "coef": 1.0
     },
     {
      "var": "watermelon acres",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 120.0
   },
   {
    "name": "watering",
